CONTRACT = {
    "http_request_duration_seconds": {
        "route": 5, "method": 4, "status_class": 3,
    },
    "orders_created_total": {"payment_kind": 4},
}

EMISSIONS = []
for i in range(200):
    EMISSIONS.append(("http_request_duration_seconds", {
        "route": f"/orders/{i}" if i % 3 == 0 else "/orders",
        "method": "GET" if i % 2 else "POST",
        "status_class": "2xx" if i % 19 else "5xx",
    }))
for i in range(40):
    labels = {"payment_kind": "card" if i % 2 else "wallet"}
    if i % 8 == 5:
        labels.pop("payment_kind")
    EMISSIONS.append(("orders_created_total", labels))
for i in range(10):
    EMISSIONS.append(("request_latency_ms", {"route": "/orders"}))


def check_emissions(contract, emissions):
    violations = set()
    seen = {}
    for name, labels in emissions:
        if name not in contract:
            violations.add(f"unknown metric '{name}' (not in contract)")
            continue
        for key in contract[name]:
            if key not in labels:
                violations.add(f"{name}: sample missing required label '{key}'")
        vals = seen.setdefault(name, {})
        for key, val in labels.items():
            if key in contract[name]:
                vals.setdefault(key, set()).add(val)
    for name, keys in seen.items():
        for key, vals in keys.items():
            budget = contract[name][key]
            if len(vals) > budget:
                violations.add(f"{name}: label '{key}' cardinality {len(vals)} > budget {budget}")
    return sorted(violations)


violations = check_emissions(CONTRACT, EMISSIONS)
for v in violations:
    print(f"VIOLATION {v}")
print(f"contract check: {len(violations)} violation(s) -> {'BUILD FAILED' if violations else 'BUILD OK'}")

