SPANS = [
    ("s1", None, "gateway",            0,    4180),
    ("s2", "s1", "orders.create",      70,   4120),
    ("s3", "s2", "inventory.check",    90,    400),
    ("s4", "s2", "payments.charge",    410,  4050),
    ("s5", "s4", "db.insert_payment",  430,   525),
    ("s6", "s2", "email.enqueue",      4060, 4120),
]


def analyze_trace(spans):
    incl = {sid: end - start for sid, _, _, start, end in spans}
    child_sum = {sid: 0 for sid, *_ in spans}
    root = None
    for sid, parent, _, _, _ in spans:
        if parent is None:
            root = sid
        else:
            child_sum[parent] += incl[sid]
    rows = []
    by_start = sorted(spans, key=lambda s: s[3])
    for sid, _, name, _, _ in by_start:
        rows.append((name, incl[sid], incl[sid] - child_sum[sid]))
    hot = max(rows, key=lambda r: r[2])
    total = incl[root]
    return {"total": total, "rows": rows, "hot": hot[0],
            "hot_self": hot[2], "hot_pct": hot[2] / total * 100}


r = analyze_trace(SPANS)
print(f"trace total: {r['total']}ms across {len(SPANS)} spans")
for name, incl, self_ms in r["rows"]:
    print(f"  {name:<18} inclusive={incl:5d}ms  self={self_ms:5d}ms")
print(f"hot span: {r['hot']} owns {r['hot_self']}ms self-time = {r['hot_pct']:.0f}% of the trace")
print(f"note: the 'slowest' span ({r['rows'][0][0]}, {r['rows'][0][1]}ms inclusive) has only {r['rows'][0][2]}ms self - it was waiting, not working")

trace-context-propagation.code:
TRACE_1 = "4bf92f3577b34da6a3ce929d0e0e4736"
SPAN_GATEWAY = "00f067aa0ba902b7"
SPAN_ORDERS = "9c1b7d2e4a5f6081"


def make_traceparent(trace_id, span_id):
    return f"00-{trace_id}-{span_id}-01"


def extract(carrier):
    tp = carrier.get("traceparent")
    if not tp:
        return None
    parts = tp.split("-")
    if len(parts) != 4:
        return None
    return (parts[1], parts[2])


def run_pipeline(propagate_queue):
    spans = []
    new_trace = iter(["e" * 32, "f" * 32])

    # gateway: root of trace 1
    spans.append(("gateway", TRACE_1, None))

    # HTTP hop: headers always carry the context
    headers = {"traceparent": make_traceparent(TRACE_1, SPAN_GATEWAY)}
    ctx = extract(headers)
    if ctx:
        spans.append(("orders", ctx[0], ctx[1]))
        orders_trace = ctx[0]
    else:
        orders_trace = next(new_trace)
        spans.append(("orders", orders_trace, None))

    # queue hop: attributes carry context only when propagated
    attrs = {}
    if propagate_queue:
        attrs["traceparent"] = make_traceparent(orders_trace, SPAN_ORDERS)
    ctx = extract(attrs)
    if ctx:
        spans.append(("worker", ctx[0], ctx[1]))
    else:
        spans.append(("worker", next(new_trace), None))
    return spans


for mode, flag in (("BEFORE (queue drops context)", False), ("AFTER (attributes carry it)", True)):
    spans = run_pipeline(flag)
    roots = sum(1 for _, _, parent in spans if parent is None)
    print(f"-- {mode} --")
    for svc, tid, parent in spans:
        print(f"  {svc:<8} trace={tid[:8]}... parent={parent[:8] + '...' if parent else 'NONE (root)'}")
    print(f"  roots: {roots} -> {'ONE trace end-to-end' if roots == 1 else 'SEVERED - orphan subtree(s)'}")

