        "threshold_ms": 800,
    },
    "error rate": {
        "query": 'rate(http_5xx{route="/checkout"}) / rate(http_total{route="/checkout"})',
        "threshold_ms": 5,
    },
    "db pool saturation": {
        "query": "max(db_pool_waiters)",
        "threshold_ms": 10,
    },
}


def diff_dashboards(old, new):
    changes = []
    for title in new:
        if title not in old:
            changes.append(f"+ panel '{title}'")
    for title in old:
        if title not in new:
            changes.append(f"- panel '{title}'")
    for title in old:
        if title in new:
            if old[title]["threshold_ms"] != new[title]["threshold_ms"]:
                changes.append(
                    f"~ '{title}' threshold_ms {old[title]['threshold_ms']} -> {new[title]['threshold_ms']}")
            if old[title]["query"] != new[title]["query"]:
                changes.append(f"~ '{title}' query changed")
    return sorted(changes)


changes = diff_dashboards(REV_41, REV_42)
print(f"dashboard diff rev41 -> rev42: {len(changes)} change(s)")
for c in changes:
    print(f"  {c}")
print("review: threshold now matches the 800ms the alert pages on; vanity CPU panel retired for a saturation panel")

alert-design.code:
SLO = 0.999

MINUTES = []
for m in range(360):
    reqs = 600 + (m * 17) % 120
    errs = 1 if m % 7 == 3 else 0
    if 100 <= m < 102:
        errs = reqs // 2
    if m >= 240:
        errs = max(errs, reqs // 200)
    MINUTES.append((reqs, errs))


def burn(minutes, window):
    tail = minutes[-window:]
    reqs = sum(r for r, _ in tail)
    errs = sum(e for _, e in tail)
    return (errs / reqs) / (1 - SLO)


def evaluate(minutes):
    fast = burn(minutes, 5)
    slow1h = burn(minutes, 60)
    slow6h = burn(minutes, 360)
    if fast >= 14.4 and slow1h >= 14.4:
        decision = "PAGE"
    elif slow6h >= 3:
        decision = "TICKET"
    else:
        decision = "NONE"
    return {"fast": fast, "slow1h": slow1h, "slow6h": slow6h, "decision": decision}


r = evaluate(MINUTES)
print(f"burn rates: 5m={r['fast']:.1f}x  1h={r['slow1h']:.1f}x  6h={r['slow6h']:.1f}x  (SLO {SLO*100:.1f}%)")
print(f"decision: {r['decision']}")
print(f"why: the 90s blip at minute 100 {'did NOT page' if r['decision'] != 'PAGE' else 'paged'} - two windows demand the budget is gone AND still burning")
print(f"the 0.5% bleed since minute 240 burns {r['slow6h']:.1f}x sustained - a ticket TODAY beats a page at month-end")

burn-rate-alerting.code:
SLO = 0.999
WINDOW_DAYS = 30


def multiplier(budget_frac, window_h):
    return budget_frac / (window_h / (WINDOW_DAYS * 24))


def hours_to_exhaustion(burn):
    return WINDOW_DAYS * 24 / burn


def classify(err_rate):
    burn = err_rate / (1 - SLO)
    page = burn >= PAGE_MULT
    return {"burn": burn, "page": page,
            "ticket": (not page) and burn >= TICKET_MULT}


PAGE_MULT = multiplier(0.02, 1)
TICKET_MULT = multiplier(0.10, 72)
print(f"derived: page at {PAGE_MULT:.1f}x (2% budget/1h) - budget dead in {hours_to_exhaustion(PAGE_MULT):.0f}h at that rate")
print(f"derived: ticket at {TICKET_MULT:.1f}x (10% budget/3d) - budget dead in {hours_to_exhaustion(TICKET_MULT):.0f}h at that rate")
for name, rate in (("total outage", 1.0), ("partial: 0.5% errors", 0.005), ("noise floor: 0.02%", 0.0002)):
    c = classify(rate)
    verdict = "PAGE" if c["page"] else ("TICKET" if c["ticket"] else "NONE")
    print(f"{name:<22} burn={c['burn']:6.1f}x exhaustion={hours_to_exhaustion(c['burn']):7.1f}h -> {verdict}")

