SLO = 0.995

EVENTS = {
    "fail_start": 21 * 60 + 40,
    "detect":     26 * 60 + 11,
    "mitigate":   26 * 60 + 24,
    "recover":    26 * 60 + 58,
}

ITEMS = [
    {"name": "freshness SLI + SLO for search index", "owner": "mira", "due": "07-28", "system_level": True},
    {"name": "updater crash-loop backoff + poison-doc quarantine", "owner": "raj", "due": "07-24", "system_level": True},
    {"name": "be more careful with doc validation", "owner": "", "due": "", "system_level": False},
    {"name": "quarterly alert-coverage review", "owner": "lead", "due": "", "system_level": True},
]


def postmortem(events, items):
    ttd = events["detect"] - events["fail_start"]
    ttm = events["mitigate"] - events["detect"]
    ttr = events["recover"] - events["fail_start"]
    stale = events["recover"] - events["fail_start"]
    budget_m = (1 - SLO) * 28 * 24 * 60
    audited = []
    for it in items:
        if not it["owner"]:
            audited.append((it["name"], False, "no owner"))
        elif not it["due"]:
            audited.append((it["name"], False, "no date"))
        elif not it["system_level"]:
            audited.append((it["name"], False, "not a system change"))
        else:
            audited.append((it["name"], True, "ok"))
    return {"ttd_m": ttd, "ttm_m": ttm, "ttr_m": ttr, "stale_m": stale,
            "burn_pct": 100 * stale / budget_m, "audited": audited}


r = postmortem(EVENTS, ITEMS)
print(f"TTD {r['ttd_m']}m | TTM {r['ttm_m']}m | TTR {r['ttr_m']}m - the system was blind, not slow")
print(f"impact: {r['stale_m']}m stale = {r['burn_pct']:.0f}% of the monthly error budget")
for name, ok, reason in r["audited"]:
    print(f"  {'PASS' if ok else 'FAIL'} [{reason}] {name}")

queue-backpressure.code:
SERVICE = 80
NORMAL, SURGE = 60, 140


def arrivals_at(tick):
    return SURGE if 10 <= tick < 100 else NORMAL


def simulate(cap):
    depth = 0
    max_depth = 0
    shed = 0
    drain_s = None
    for tick in range(400):
        arr = arrivals_at(tick)
        if cap is None:
            admit = arr
        else:
            admit = min(arr, cap + SERVICE - depth)
            shed += arr - admit
        depth = max(0, depth + admit - SERVICE)
        max_depth = max(max_depth, depth)
        if tick >= 100 and depth == 0 and drain_s is None:
            drain_s = tick - 100
    return {"max_depth": max_depth, "max_wait_s": max_depth / SERVICE,
            "shed": shed, "drain_s": drain_s}


for label, cap in (("unbounded", None), ("bounded@50", 50)):
    r = simulate(cap)
    print(f"{label:<11} max_depth={r['max_depth']:5d}  worst_wait={r['max_wait_s']:6.2f}s  shed={r['shed']:5d}  drain_after_surge={r['drain_s']}s")
u, b = simulate(None), simulate(50)
print(f"the trade: unbounded made EVERYONE wait up to {u['max_wait_s']:.0f}s and kept hurting {u['drain_s']}s after the surge;")
print(f"bounded held wait under {b['max_wait_s']:.2f}s, shed {b['shed']} requests as fast 503s, recovered in {b['drain_s']}s")

release-observability.code:
import math

SLO = 0.999
RULES = {"hold_p99_delta": 0.20, "hold_err_mult": 2.0,
         "rollback_burn": 10.0, "rollback_err_mult": 5.0}

def window(err_every, slow_every, base_ms, n=2000):
    out = []
    for i in range(n):
        lat = base_ms + (i * 41) % 220
        if slow_every and i % slow_every == 3:
            lat = base_ms * 6
        out.append((lat, bool(err_every) and i % err_every == 7))
    return out

PRE            = window(err_every=500, slow_every=0,   base_ms=420)
POST_HEALTHY   = window(err_every=500, slow_every=0,   base_ms=430)
POST_BAD       = window(err_every=55,  slow_every=40,  base_ms=430)


def judge_release(pre, post, rules):
    def p99(w):
        s = sorted(l for l, _ in w)
        return s[math.ceil(0.99 * len(s)) - 1]
    def err_rate(w):
        return sum(1 for _, e in w if e) / len(w)
    p99_pre, p99_post = p99(pre), p99(post)
    er_pre, er_post = err_rate(pre), err_rate(post)
    p99_delta = (p99_post - p99_pre) / p99_pre
    err_mult = er_post / er_pre
    burn = er_post / (1 - SLO)
    if burn > rules["rollback_burn"] or err_mult > rules["rollback_err_mult"]:
        verdict = "ROLLBACK"
    elif p99_delta > rules["hold_p99_delta"] or err_mult > rules["hold_err_mult"]:
        verdict = "HOLD"
    else:
        verdict = "SHIP"
    return {"p99_delta": p99_delta, "err_mult": err_mult, "burn": burn, "verdict": verdict}


for name, post in (("v419 (healthy)", POST_HEALTHY), ("v419' (counterfactual)", POST_BAD)):
    r = judge_release(PRE, post, RULES)
    print(f"{name:<24} p99_delta={r['p99_delta']*100:+.1f}%  err_mult={r['err_mult']:.1f}x  burn={r['burn']:.1f}x  -> {r['verdict']}")
print("the frame decided both in seconds: no debate while the budget drains, and the healthy release ships despite a noisy fleet")
